window.DEX_DATA["sources:backport-4b140d359eeae397"]={"json":{"skins":[{"filename":"piratecaptain.png"}],"names":[{"name":"方块胡子船长"},{"name":"克鲁克船长"},{"name":"铁螯龙虾船长"},{"name":"摩根船长"},{"name":"独脚约翰·西尔弗"}],"chat":[{"lines":[{"text":"我们以前把宝藏埋在红叉下面，可总有人偷走。"},{"text":"于是我们学聪明了，把宝藏藏得更巧妙。"},{"text":"比如两棵交叉成叉形的棕榈树下面。"}]},{"lines":[{"text":"你的宝藏都是我的！"}]},{"lines":[{"text":"从海底神殿里搬金子，比掰开贝壳还难！"}]},{"lines":[{"text":"带橙子了吗？我的船员都快得坏血病了。"}]}]}};
